SABA
Downloading SABA prescription data from OpenPrescribing for all Sub-ICB areas. This updates the records if the last download was more than 10 weeks ago.


Show the code
saba_update_check &lt;- function() {
  last_file &lt;- file.path(here(), "data_raw", "all_saba.csv")
  if (file.exists(last_file)) {
    lastfile_info &lt;- file.info(last_file)
    elapsed_wks &lt;- difftime(Sys.time(), lastfile_info$mtime, units = "weeks") |&gt;
      as.numeric()
  } else {
    return("download")
  }

  if (elapsed_wks &gt; 10) {
    return("update")
  } else {
    return("load")
  }
}

cur_saba_status &lt;- saba_update_check()


if (cur_saba_status == "download") {
  all_saba_raw &lt;- do.call(
    bind_rows,
    lapply(subicb_boundaries$code, \(t_code) {
      read_csv(
        paste0(
          "https://openprescribing.net/api/1.0/measure_by_practice/?format=csv&org=",
          t_code,
          "&parent_org_type=ccg&measure=saba"
        ),
        col_types = cols(
          measure = col_character(),
          org_type = col_character(),
          org_id = col_character(),
          org_name = col_character(),
          date = col_date(format = ""),
          numerator = col_double(),
          denominator = col_double(),
          calc_value = col_double(),
          percentile = col_double()
        )
      )
    })
  )
  write_csv(all_saba_raw, file = file.path(here(), "data_raw", "all_saba.csv"))
} else if (cur_saba_status == "update") {
  new_saba_raw &lt;- do.call(
    bind_rows,
    lapply(subicb_boundaries$code, \(t_code) {
      read_csv(
        paste0(
          "https://openprescribing.net/api/1.0/measure_by_practice/?format=csv&org=",
          t_code,
          "&parent_org_type=ccg&measure=saba"
        ),
        col_types = cols(
          measure = col_character(),
          org_type = col_character(),
          org_id = col_character(),
          org_name = col_character(),
          date = col_date(format = ""),
          numerator = col_double(),
          denominator = col_double(),
          calc_value = col_double(),
          percentile = col_double()
        )
      )
    })
  )

  write_csv(
    new_saba_raw,
    file = file.path(
      here(),
      "data_raw",
      paste0("all_saba_", Sys.Date(), ".csv")
    )
  )

  old_saba_raw &lt;- read_csv(file = file.path(here(), "data_raw", "all_saba.csv"))

  new_saba_raw_filtered &lt;- new_saba_raw |&gt;
    anti_join(old_saba_raw, by = join_by(date, measure, org_id))

  all_saba_raw &lt;- old_saba_raw |&gt;
    bind_rows(new_saba_raw_filtered)

  write_csv(
    all_saba_raw,
    file = file.path(here(), "data_raw", "all_saba.csv"),
    append = FALSE
  )
} else {
  all_saba_raw &lt;- read_csv(file = file.path(here(), "data_raw", "all_saba.csv"))
}

