# Helper function to read from the OpenPrescribing API with browser headers to avoid Cloudflare blocks
read_openprescribing &lt;- function(url) {
  resp &lt;- GET(
    url,
    add_headers(Accept = "application/json"),
    user_agent("R httr")
  )
  stop_for_status(resp)
  content(resp, as = "text", encoding = "UTF-8")
}

# Define a robust download helper function with rate-limiting and error handling
download_bnf_grid &lt;- function(grid_df) {
  dir.create("data_raw/bnf_all", showWarnings = FALSE)
  for (i in seq_len(nrow(grid_df))) {
    dest &lt;- file.path("data_raw", "bnf_all", grid_df$file.name[i])
    if (!file.exists(dest)) {
      url &lt;- paste0(
        "https://openprescribing.net/api/1.0/spending_by_org/?org_type=practice&code=",
        grid_df$code[i],
        "&date=",
        grid_df$date[i],
        "&format=csv"
      )
      tryCatch(
        {
          csv_text &lt;- read_openprescribing(url)

          # Verify response looks like a CSV (not empty and not HTML)
          if (
            nchar(csv_text) &gt; 50 &&
              !grepl("&lt;!DOCTYPE html&gt;", csv_text, fixed = TRUE)
          ) {
            writeLines(csv_text, dest, useBytes = TRUE)
            Sys.sleep(0.1) # be considerate to the API rate limit
          } else {
            warning(paste("Invalid file content returned for:", url))
          }
        },
        error = function(e) {
          warning(paste("Failed to download:", url, "-", e$message))
          if (file.exists(dest)) file.remove(dest)
        }
      )
    }
  }
}

all_data_group2 &lt;- full_data_grid |&gt; filter(group == 2)
download_bnf_grid(all_data_group2)




